    #[test]
    fn init_escribe_tres_archivos_en_dir_vacio() {
        let dir = tempdir().expect("tempdir");
        let shape = DockerShape {
            package_name: "demo".into(),
            server_port: Some(3000),
            uses_db: false,
            ..Default::default()
        };
        let result = init(dir.path(), &shape, false).expect("init ok");
        assert_eq!(result.written.len(), 3);
        assert!(result.skipped.is_empty());
        assert!(dir.path().join("Dockerfile").exists());
        assert!(dir.path().join(".dockerignore").exists());
        assert!(dir.path().join("docker-compose.yml").exists());
    }

    #[test]
    fn init_skipea_archivos_existentes_sin_force() {
        let dir = tempdir().expect("tempdir");
        fs::write(dir.path().join("Dockerfile"), "viejo contenido").unwrap();
        let shape = DockerShape {
            package_name: "demo".into(),
            server_port: None,
            uses_db: false,
            ..Default::default()
        };
        let result = init(dir.path(), &shape, false).expect("init ok");
        assert_eq!(result.written.len(), 2);
        assert_eq!(result.skipped.len(), 1);
        assert_eq!(
            result.skipped[0].file_name().and_then(|s| s.to_str()),
            Some("Dockerfile"),
        );
        // And the old file is preserved.
        let viejo = fs::read_to_string(dir.path().join("Dockerfile")).unwrap();
        assert_eq!(viejo, "viejo contenido");
    }

    #[test]
    fn init_force_sobrescribe_archivos_existentes() {
        let dir = tempdir().expect("tempdir");
        fs::write(dir.path().join(".dockerignore"), "viejo").unwrap();
        let shape = DockerShape {
            package_name: "demo".into(),
            server_port: None,
            uses_db: false,
            ..Default::default()
        };
        let result = init(dir.path(), &shape, true).expect("init ok");
        assert_eq!(result.written.len(), 3);
        assert!(result.skipped.is_empty());
        let nuevo = fs::read_to_string(dir.path().join(".dockerignore")).unwrap();
        assert!(nuevo.contains("target/"));
    }

    #[test]
    fn init_error_si_target_dir_no_existe() {
        let shape = DockerShape {
            package_name: "demo".into(),
            server_port: None,
            uses_db: false,
            ..Default::default()
        };
        let result = init(Path::new("/no/existe/aca"), &shape, false);
        assert!(result.is_err());
    }

    // ---- 12.4.b — uses_python / uses_cron / conditional healthcheck ----

    #[test]
    fn detect_shape_uses_python_con_from_import() {
        let src = r#"
from python import math

fn area(r: Float) -> Float => math.pi * r * r
"#;
        let shape = shape_from_source(src, "demo");
        assert!(shape.uses_python);
        assert!(!shape.uses_cron);
    }

    #[test]
    fn detect_shape_uses_python_con_import_directo() {
        let src = r#"
import python
"#;
        let shape = shape_from_source(src, "demo");
        assert!(shape.uses_python);
    }

    #[test]
    fn detect_shape_sin_python_no_dispara_uses_python() {
        let src = r#"
import utils
from helpers import double
"#;
        // Imports to other modules are not Python interop.
        let shape = shape_from_source(src, "demo");
        assert!(!shape.uses_python);
    }

    #[test]
    fn detect_shape_uses_cron_con_decorator() {
        let src = r#"
@cron("0 * * * *")
fn limpiar() => 0
"#;
        let shape = shape_from_source(src, "demo");
        assert!(shape.uses_cron);
    }

    #[test]
    fn detect_shape_sin_cron_no_dispara_uses_cron() {
        let src = r#"
@get("/")
fn root() => "ok"

@server(3000)
fn main() => 0
"#;
        let shape = shape_from_source(src, "demo");
        assert!(!shape.uses_cron);
    }

    #[test]
    fn render_dockerfile_con_python_runtime_es_slim_bookworm() {
        let shape = DockerShape {
            package_name: "demo".into(),
            server_port: Some(3000),
            uses_python: true,
            ..Default::default()
        };
        let dockerfile = render_dockerfile(&shape);
        assert!(dockerfile.contains("FROM python:3.12-slim-bookworm"));
        assert!(!dockerfile.contains("FROM gcr.io/distroless/cc-debian12"));
        // Comment explaining why the runtime is different.
        assert!(dockerfile.contains("libpython3.12"));
    }

    #[test]
    fn render_dockerfile_sin_python_runtime_es_distroless() {
        let shape = DockerShape {
            package_name: "demo".into(),
            server_port: Some(3000),
            uses_python: false,
            ..Default::default()
        };
        let dockerfile = render_dockerfile(&shape);
        assert!(dockerfile.contains("FROM gcr.io/distroless/cc-debian12"));
        assert!(!dockerfile.contains("python:3.12-slim-bookworm"));
    }

